static std::wstring Id(IMMDevice* d){LPWSTR p=nullptr;std::wstring s;if(d&&SUCCEEDED(d->GetId(&p))){s=p;CoTaskMemFree(p);}return s;}
static std::wstring Name(IMMDevice* d){if(!d)return {};ComPtr<IPropertyStore> p;PROPVARIANT v;PropVariantInit(&v);std::wstring s;if(SUCCEEDED(d->OpenPropertyStore(STGM_READ,&p))&&SUCCEEDED(p->GetValue(PKEY_Device_FriendlyName,&v))&&v.vt==VT_LPWSTR)s=v.pwszVal;PropVariantClear(&v);return s;}
static std::wstring targetName=L"AirPods";
static ComPtr<IMMDevice> Find(IMMDeviceEnumerator* e,EDataFlow f){ComPtr<IMMDeviceCollection> list;ComPtr<IMMDevice> result;if(FAILED(e->EnumAudioEndpoints(f,DEVICE_STATE_ACTIVE,&list)))return result;UINT n=0;list->GetCount(&n);for(UINT i=0;i<n;i++){ComPtr<IMMDevice> d;if(FAILED(list->Item(i,&d)))continue;auto name=Name(d.Get());if(name.find(targetName)==name.npos)continue;if(!result)result=d;if(f==eCapture&&name.find(L"A2DP")!=name.npos)return d;}return result;}
static ComPtr<IMMDevice> FallbackMic(IMMDeviceEnumerator* e){ComPtr<IMMDeviceCollection> list;ComPtr<IMMDevice> first;if(FAILED(e->EnumAudioEndpoints(eCapture,DEVICE_STATE_ACTIVE,&list)))return first;UINT n=0;list->GetCount(&n);for(UINT i=0;i<n;i++){ComPtr<IMMDevice>d;if(FAILED(list->Item(i,&d)))continue;auto name=Name(d.Get());if(name.find(L"AirPods")!=name.npos)continue;if(!first)first=d;if(name.find(L"Realtek")!=name.npos)return d;}return first;}
extern "C" __declspec(dllexport) void AirPodsAudioInitialize(PCWSTR file){profile=file?file:L"";}
extern "C" __declspec(dllexport) int AirPodsAudioSnapshot(int* values){if(!values)return E_POINTER;for(int i=0;i<5;i++)values[i]=-1;Apartment a;ComPtr<IMMDeviceEnumerator> e;HRESULT hr=CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_ALL,IID_PPV_ARGS(&e));if(FAILED(hr))return hr;auto output=Find(e.Get(),eRender),mic=Find(e.Get(),eCapture);values[4]=mic&&Name(mic.Get()).find(L"A2DP")!=std::wstring::npos;if(output){ComPtr<IAudioEndpointVolume> v;if(SUCCEEDED(output->Activate(__uuidof(IAudioEndpointVolume),CLSCTX_ALL,nullptr,reinterpret_cast<void**>(v.GetAddressOf())))){float level=0;v->GetMasterVolumeLevelScalar(&level);values[0]=int(level*100+.5f);}ComPtr<IMMDevice> def;e->GetDefaultAudioEndpoint(eRender,eMultimedia,&def);values[2]=Id(output.Get())==Id(def.Get());}if(mic){ComPtr<IAudioEndpointVolume> v;if(SUCCEEDED(mic->Activate(__uuidof(IAudioEndpointVolume),CLSCTX_ALL,nullptr,reinterpret_cast<void**>(v.GetAddressOf())))){BOOL mute=FALSE;v->GetMute(&mute);values[1]=mute;}ComPtr<IMMDevice> def;e->GetDefaultAudioEndpoint(eCapture,eCommunications,&def);values[3]=Id(mic.Get())==Id(def.Get());}return 0;}
extern "C" __declspec(dllexport) int AirPodsAudioCommand(int command,int value){Apartment a;ComPtr<IMMDeviceEnumerator> e;HRESULT hr=CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_ALL,IID_PPV_ARGS(&e));if(FAILED(hr))return hr;auto d=Find(e.Get(),command==13||command==16?eCapture:eRender);if(command==18){ComPtr<Policy> p;if(FAILED(hr=CoCreateInstance(PolicyClass,nullptr,CLSCTX_ALL,PolicyIid,reinterpret_cast<void**>(p.GetAddressOf()))))return hr;for(int i=0;i<3;i++){wchar_t prior[1024]{},selected[1024]{};auto k=L"PreviousMic"+std::to_wstring(i);GetPrivateProfileStringW(L"Audio",k.c_str(),L"",prior,1024,profile.c_str());GetPrivateProfileStringW(L"Audio",L"SelectedMic",L"",selected,1024,profile.c_str());ComPtr<IMMDevice> current,saved;e->GetDefaultAudioEndpoint(eCapture,ERole(i),&current);if(selected[0]&&Id(current.Get())==selected){DWORD state=0;if(prior[0]&&SUCCEEDED(e->GetDevice(prior,&saved)))saved->GetState(&state);if(state!=DEVICE_STATE_ACTIVE||Name(saved.Get()).find(L"AirPods")!=std::wstring::npos)saved=FallbackMic(e.Get());if(saved){auto restore=Id(saved.Get());hr=p->SetDefaultEndpoint(restore.c_str(),ERole(i));if(FAILED(hr))return hr;}else return HRESULT_FROM_WIN32(ERROR_NOT_FOUND);}}return 0;}if(!d)return HRESULT_FROM_WIN32(ERROR_NOT_CONNECTED);
 if(command==12||command==13){ComPtr<IAudioEndpointVolume> v;hr=d->Activate(__uuidof(IAudioEndpointVolume),CLSCTX_ALL,nullptr,reinterpret_cast<void**>(v.GetAddressOf()));if(FAILED(hr))return hr;return command==12?v->SetMasterVolumeLevelScalar(std::clamp(value,0,100)/100.f,nullptr):v->SetMute(value!=0,nullptr);}
 if(command==14||command==16){ComPtr<Policy> p;if(FAILED(hr=CoCreateInstance(PolicyClass,nullptr,CLSCTX_ALL,PolicyIid,reinterpret_cast<void**>(p.GetAddressOf()))))return hr;auto target=Id(d.Get());for(int i=0;i<3;i++){if(command==16){ComPtr<IMMDevice> current;e->GetDefaultAudioEndpoint(eCapture,ERole(i),&current);auto previous=Id(current.Get());if(previous!=target&&!previous.empty()&&Name(current.Get()).find(L"AirPods")==std::wstring::npos){auto key=L"PreviousMic"+std::to_wstring(i);WritePrivateProfileStringW(L"Audio",key.c_str(),previous.c_str(),profile.c_str());}}hr=p->SetDefaultEndpoint(target.c_str(),ERole(i));if(FAILED(hr))return hr;}if(command==16)WritePrivateProfileStringW(L"Audio",L"SelectedMic",target.c_str(),profile.c_str());return 0;}return E_INVALIDARG;}

